function collect({ gnews, news }) {
  function validUrl(value) {
    if (
      typeof value !== "string" ||
      /[\s\x00-\x1f\x7f\\]/.test(value) ||
      /%(?![0-9a-f]{2})/i.test(value)
    )
      return false;
    const match = /^https?:\/\/([^/?#]+)(?:[/?#].*)?$/i.exec(value);
    if (!match || match[1].includes("@")) return false;
    const authority = match[1];
    let host, port;
    if (authority.startsWith("[")) {
      const parts = /^\[([0-9a-f:]+)\](?::(\d+))?$/i.exec(authority);
      if (!parts) return false;
      host = parts[1];
      port = parts[2];
      const halves = host.split("::");
      if (halves.length > 2) return false;
      const groups = halves.flatMap((part) => (part ? part.split(":") : []));
      if (groups.some((group) => !/^[0-9a-f]{1,4}$/i.test(group))) return false;
      if (halves.length === 1 ? groups.length !== 8 : groups.length >= 8) return false;
    } else {
      const parts = /^([^:]+)(?::(\d+))?$/.exec(authority);
      if (!parts) return false;
      host = parts[1];
      port = parts[2];
      if (host.length > 253) return false;
      const labels = host.replace(/\.$/, "").split(".");
      if (
        !labels.every(
          (label) =>
            label.length > 0 &&
            label.length <= 63 &&
            /^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?$/i.test(label),
        )
      )
        return false;
      if (
        labels.every((label) => /^\d+$/.test(label)) &&
        (labels.length !== 4 || labels.some((label) => Number(label) > 255))
      )
        return false;
    }
    return port === undefined || (port.length <= 5 && Number(port) <= 65535);
  }
  if (
    !gnews ||
    !Array.isArray(gnews.articles) ||
    !news ||
    news.status !== "ok" ||
    !Array.isArray(news.articles)
  )
    throw Error("Invalid news response");
  const seen = new Set(),
    articles = [];
  for (const a of [...gnews.articles, ...news.articles]) {
    if (
      !a ||
      typeof a.title !== "string" ||
      !a.title.trim() ||
      typeof a.url !== "string" ||
      !validUrl(a.url)
    )
      throw Error("Invalid article");
    if (seen.has(a.url)) continue;
    seen.add(a.url);
    articles.push({
      title: a.title,
      url: a.url,
      description: typeof a.description === "string" ? a.description : "",
      content: typeof a.content === "string" ? a.content : "",
      publishedAt: typeof a.publishedAt === "string" ? a.publishedAt : "",
    });
  }
  return {
    articlesJson: JSON.stringify(articles),
    urls: articles.map((a) => a.url),
    count: Math.min(15, articles.length),
    hasArticles: articles.length > 0,
  };
}

return [
  { json: collect({ gnews: $("Fetch GNews articles").first().json, news: $input.first().json }) },
];

function format({ result, urls, count }) {
  if (
    !result ||
    !Array.isArray(result.items) ||
    !Array.isArray(urls) ||
    !Number.isInteger(count) ||
    result.items.length !== count
  )
    throw Error("Incomplete news selection");
  const used = new Set(),
    items = result.items.map((x) => {
      if (
        !x ||
        typeof x.url !== "string" ||
        !urls.includes(x.url) ||
        used.has(x.url) ||
        typeof x.title !== "string" ||
        !x.title.trim() ||
        /https?:\/\//i.test(x.title) ||
        typeof x.summary !== "string" ||
        !x.summary.trim() ||
        /https?:\/\//i.test(x.summary)
      )
        throw Error("Invalid selected article");
      used.add(x.url);
      return `${x.title.trim()}\n${x.summary.trim()}\n${x.url}`;
    });
  const day = new Date().toISOString().slice(0, 10).replace(/-/g, "/"),
    text = `早安，這是 ${day} 的 AI 新聞：\n\n${items.join("\n\n")}`;
  if (text.length > 4096) throw Error("News digest exceeds Telegram message limit");
  return { text };
}

const a = $("Combine the articles").first().json;
const x = format({ result: $input.first().json.output, urls: a.urls, count: a.count });
return [
  { json: { text: x.text.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;") } },
];
